/**
 * Y90 Compass Clinical Logic
 * Yttrium-90 Radioembolization Decision Support
 * Based on EASL 2024, AASLD 2023, SIR Guidelines 2024
 */

export interface Y90PatientData {
  diagnosis: "hcc" | "icca" | "other";
  bclcStage?: "0" | "a" | "b" | "c" | "d";
  iccaTreatmentLine?: "first-line" | "second-line" | "neoadjuvant";
  portalVeinInvolvement?: "none" | "branch" | "main";
  taceFeasibility?: "eligible" | "refractory" | "diffuse";
  tumorSize?: number; // in cm
  tumorCount?: number;
  childPughScore?: "a" | "b" | "c";
  ecogPerformanceStatus?: 0 | 1 | 2 | 3;
  priorTACE?: boolean;
  taceRefractory?: boolean;
  liverFunction?: "preserved" | "impaired" | "advanced";
  extrahepticSpread?: boolean;
}

export interface Y90AssessmentResult {
  candidacy: "eligible" | "not-eligible" | "caution";
  summary: string;
  recommendations: string[];
  contraindications: string[];
  dosimetryNotes: string;
  followUpSchedule: string[];
  references: string[];
}

/**
 * Assess Y90 candidacy based on patient and tumor characteristics
 */
export function assessY90Candidacy(data: Y90PatientData): Y90AssessmentResult {
  const contraindications: string[] = [];
  const recommendations: string[] = [];
  let candidacy: "eligible" | "not-eligible" | "caution" = "caution";
  let dosimetryNotes = "";
  let summary = "";

  // HCC assessment pathway
  if (data.diagnosis === "hcc") {
    // BCLC-D: Not eligible
    if (data.bclcStage === "d") {
      candidacy = "not-eligible";
      summary = "Y90 is not indicated in BCLC-D (Child-Pugh C, ECOG PS >2). Best supportive care recommended.";
      contraindications.push("BCLC-D stage with terminal liver disease");
      contraindications.push("Child-Pugh C cirrhosis");
      contraindications.push("ECOG performance status >2");
    }
    // BCLC 0/A: Early stage
    else if (data.bclcStage === "0" || data.bclcStage === "a") {
      if (data.tumorSize && data.tumorSize <= 5 && data.tumorCount === 1) {
        candidacy = "eligible";
        summary = "Y90 radiation segmentectomy is indicated for solitary HCC ≤5 cm in non-surgical candidates (LEGACY Trial).";
        dosimetryNotes = "Target dose ≥400 Gy (glass) or ≥150 Gy (resin) to treated segment. Complete pathologic necrosis rates ~50-60%.";
        recommendations.push("Superselective catheterization technique");
        recommendations.push("Personalized dosimetry planning");
        recommendations.push("Consider bridge-to-transplant strategy");
      } else if (data.tumorSize && data.tumorSize > 5) {
        candidacy = "caution";
        summary = "Tumor >5 cm may require radiation lobectomy. Requires adequate future liver remnant (FLR).";
        contraindications.push("Inadequate future liver remnant (<25%)");
        recommendations.push("Volumetric assessment for lobectomy");
        recommendations.push("Contralateral hypertrophy monitoring (6-8 weeks)");
      }
    }
    // BCLC B: Intermediate stage
    else if (data.bclcStage === "b") {
      if (data.taceFeasibility === "eligible") {
        candidacy = "caution";
        summary = "TACE remains standard first-line for BCLC-B. Y90 is alternative for large (>5 cm) or bilobar disease per EASL 2024.";
        recommendations.push("Consider Y90 for large or bilobar tumors");
        recommendations.push("Discuss TACE vs. Y90 in multidisciplinary setting");
      } else if (data.taceFeasibility === "refractory") {
        candidacy = "eligible";
        summary = "Y90 is indicated as alternative locoregional therapy for TACE-refractory intermediate HCC. Per EASL 2024, Y90 recommended alternative to TACE.";
        dosimetryNotes = "Personalized dosimetry recommended (≥205 Gy target dose, glass microspheres).";
        recommendations.push("Y90 radiation segmentectomy or lobectomy based on tumor extent");
        recommendations.push("Comparable OS to TACE with potentially better quality of life");
      } else if (data.taceFeasibility === "diffuse") {
        candidacy = "caution";
        summary = "Diffuse/infiltrative HCC pattern may limit TACE efficacy. Y90 may be considered for liver-dominant disease.";
        recommendations.push("Consider Y90 for diffuse HCC patterns");
        recommendations.push("Multidisciplinary evaluation recommended");
      } else {
        candidacy = "caution";
        summary = "TACE remains standard first-line for BCLC-B. Y90 may be preferred for large or bilobar disease.";
        recommendations.push("Discuss TACE vs. Y90 in multidisciplinary setting");
      }
    }
    // BCLC C: Advanced stage
    else if (data.bclcStage === "c") {
      if (data.portalVeinInvolvement === "branch") {
        candidacy = "eligible";
        summary = "Y90 is indicated and safe in branch portal vein thrombosis (Vp1-Vp3). Median OS 14-17 months with optimized dosing.";
        dosimetryNotes = "Lobar Y90 with personalized dosimetry recommended.";
        recommendations.push("YES-P Trial evidence supports safety in PVT");
        recommendations.push("Hepatopetal flow assessment essential");
      } else if (data.portalVeinInvolvement === "main") {
        candidacy = "caution";
        summary = "Y90 may be considered in selected cases with main portal vein involvement if hepatopetal flow preserved. Higher risk.";
        contraindications.push("Hepatofugal portal vein flow");
        recommendations.push("Expert center evaluation required");
        recommendations.push("Systemic therapy (atezolizumab + bevacizumab) is standard");
      } else {
        candidacy = "caution";
        summary = "For BCLC-C without PVT, systemic therapy is first-line. Y90 may be considered in liver-dominant disease.";
        recommendations.push("Consider combination with systemic therapy");
      }
    }
  }
  // iCCA assessment pathway
  else if (data.diagnosis === "icca") {
    if (data.iccaTreatmentLine === "first-line") {
      candidacy = "eligible";
      summary = "Y90 can be combined with gemcitabine/cisplatin ± durvalumab for unresectable iCCA. Median OS 18-22 months.";
      dosimetryNotes = "Personalized dosimetry recommended (≥150 Gy target).";
      recommendations.push("Combination with systemic chemotherapy");
      recommendations.push("Consider durvalumab addition per TOPAZ-1");
    } else if (data.iccaTreatmentLine === "second-line") {
      candidacy = "eligible";
      summary = "Y90 is indicated for liver-dominant iCCA progressing on systemic therapy. Objective response rates 20-35%.";
      recommendations.push("Adequate liver function required (Child-Pugh A)");
      recommendations.push("Consider if liver-dominant disease");
    } else if (data.iccaTreatmentLine === "neoadjuvant") {
      candidacy = "caution";
      summary = "Limited data for Y90 as downstaging in iCCA. May be considered in borderline resectable cases.";
      recommendations.push("Multidisciplinary evaluation essential");
      recommendations.push("Expert center experience recommended");
    }
  }
  // Other primary liver malignancies
  else {
    candidacy = "caution";
    summary = "Y90 data is limited for other primary liver tumors. Case-by-case evaluation recommended.";
    recommendations.push("Multidisciplinary tumor board discussion");
    recommendations.push("Limited evidence base for non-HCC/iCCA tumors");
  }

  // General contraindications
  if (data.childPughScore === "c") {
    contraindications.push("Child-Pugh C cirrhosis");
  }
  if (data.ecogPerformanceStatus && data.ecogPerformanceStatus > 2) {
    contraindications.push("ECOG performance status >2");
  }

  const followUpSchedule = [
    "4-6 weeks post-Y90: Clinical assessment, labs (bilirubin, albumin, INR)",
    "8-12 weeks: Imaging (CT/MRI) to assess treatment response",
    "3-6 months: Repeat imaging and tumor markers",
    "Every 3 months: Ongoing surveillance per AASLD/EASL guidelines",
  ];

  const references = [
    "EASL Clinical Practice Guidelines: HCC (2024 Update)",
    "AASLD Guidance: HCC (2023)",
    "LEGACY Trial (Lewandowski et al., 2023)",
    "YES-P Trial (Salem et al., 2024)",
    "SIR Guidelines for Y90 Radioembolization (2024)",
    "DOSISPHERE-01 Trial (Garin et al., 2021)",
    "2025 TheraSphere Global Steering Committee Recommendations",
  ];

  return {
    candidacy,
    summary,
    recommendations,
    contraindications,
    dosimetryNotes,
    followUpSchedule,
    references,
  };
}

/**
 * Generate a clinical summary for Y90 assessment
 */
export function generateY90Summary(result: Y90AssessmentResult): string {
  let summary = `**Y90 Candidacy: ${result.candidacy.toUpperCase()}**\n\n`;
  summary += `${result.summary}\n\n`;

  if (result.dosimetryNotes) {
    summary += `**Dosimetry Notes:**\n${result.dosimetryNotes}\n\n`;
  }

  if (result.recommendations.length > 0) {
    summary += `**Recommendations:**\n`;
    result.recommendations.forEach((rec) => {
      summary += `• ${rec}\n`;
    });
    summary += "\n";
  }

  if (result.contraindications.length > 0) {
    summary += `**Contraindications:**\n`;
    result.contraindications.forEach((contra) => {
      summary += `• ${contra}\n`;
    });
    summary += "\n";
  }

  if (result.followUpSchedule.length > 0) {
    summary += `**Follow-up Schedule:**\n`;
    result.followUpSchedule.forEach((followUp) => {
      summary += `• ${followUp}\n`;
    });
  }

  return summary;
}
